import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`vs-manus`,hasInputUrl:!1,heroTitle:`19 AI Models. One System. Every Workflow.`,heroSubtitle:`Computer goes beyond chat replies and demos. It's a digital worker that orchestrates 19 AI models, spawns sub-agents, and runs multi-hour workflows across your entire tool stack.`,heroOverlaySteps:[`Analyzing your workflow requirements and task complexity`,`Matching specialized agents to each step of your project`,`Orchestrating models across research, analysis, and execution`,`Multi-step workflow complete with verified deliverables — ready to use`],generatingSteps:[`Scoping your project into discrete tasks and dependencies`,`Designing an agent to orchestrate 19 models across every step of your workflow`,`Configuring multi-hour execution with real-time progress tracking and error recovery`,`Setting up deliverable verification and output formatting`],featureSectionTitle:`From prompt to finished project`,featureCardTitles:[`Connects to your entire stack`,`Outputs you can ship`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Slack, GitHub, Airtable, Google Analytics — Computer plugs into your tools so workflows run end-to-end without manual handoffs.`,`Research reports. Competitive analyses. In head-to-head tests, Computer completed tasks 5-10x faster than Manus — finishing in 60 seconds what took Manus 10 minutes.`],capabilitySectionTitle:`Your digital worker, on autopilot`,capabilitySectionSubtitle:`Describe the project, step away, come back to finished work.`,capabilityCards:[{title:`Multi-Hour Workflows`,description:`Computer can run complex projects for hours — researching, writing, building, and iterating across dozens of steps without losing context or stopping.`},{title:`19-Model Orchestration`,description:`Computer can assign each subtask to the best AI model — coding with one, research with another, analysis with a third — so every step gets expert-level output.`},{title:`Real Browser Execution`,description:`Computer can navigate live websites, fill forms, extract data, and interact with web apps — not just generate text about them.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Google Drive, Notion, Slack, GitHub, and more — build workflows that span your entire tool stack.`},{title:`Memory Across Sessions`,description:`Computer can remember your preferences, past projects, and context across sessions — so every workflow builds on what it already knows about your work.`},{title:`Monitor & Rerun`,description:`Computer can schedule recurring workflows, monitor for changes, and alert you when new action is needed — hands-free operations on your terms.`}]});export{t as default};
